package com.hotelmanagement.hms.maintenance.service; import com.hotelmanagement.hms.maintenance.dto.*; import com.hotelmanagement.hms.maintenance.model.*; import com.hotelmanagement.hms.maintenance.repository.*; import com.hotelmanagement.hms.room.repository.RoomRepository; import com.hotelmanagement.hms.room.model.RoomOperationalState; import com.hotelmanagement.hms.shared.service.OperationScope; import com.hotelmanagement.hms.shared.web.*; import com.hotelmanagement.hms.audit.service.AuditService; import static com.hotelmanagement.hms.identity.authorization.model.PermissionCode.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.util.*; @Service @Transactional public class MaintenanceService { private final MaintenanceRepository repo;private final RoomRepository rooms;private final OperationScope scope;private final AuditService audit; public MaintenanceService(MaintenanceRepository r,RoomRepository rr,OperationScope s,AuditService a){repo=r;rooms=rr;scope=s;audit=a;} public MaintenanceResponse create(UUID h,UUID b,MaintenanceRequest r){UUID actor=scope.branch(h,b,MAINTENANCE_MANAGE);if(r.roomId()!=null){var room=rooms.lock(r.roomId(),h,b).orElseThrow(ApiException::notFound);room.operational(RoomOperationalState.MAINTENANCE);}var e=repo.saveAndFlush(MaintenanceTicket.create(h,b,r.roomId(),r.issue(),r.priority(),actor));audit.record(h,b,actor,"MAINTENANCE_OPENED","MAINTENANCE",e.getId());return MaintenanceResponse.from(e);} public MaintenanceResponse update(UUID h,UUID b,UUID id,MaintenanceStatus s){UUID actor=scope.branch(h,b,MAINTENANCE_MANAGE);var e=repo.findByIdAndHotelIdAndBranchId(id,h,b).orElseThrow(ApiException::notFound);e.transition(s);if(s==MaintenanceStatus.RESOLVED&&e.getRoomId()!=null)rooms.lock(e.getRoomId(),h,b).ifPresent(r->r.operational(RoomOperationalState.AVAILABLE));audit.record(h,b,actor,"MAINTENANCE_"+s,"MAINTENANCE",id);return MaintenanceResponse.from(e);} @Transactional(readOnly=true) public PageResponse<MaintenanceResponse> list(UUID h,UUID b,int p,int z){scope.branch(h,b,MAINTENANCE_VIEW);return PageResponse.from(repo.findByHotelIdAndBranchId(h,b,scope.page(p,z)).map(MaintenanceResponse::from));} }
